*{box-sizing:border-box} :root{--ink:#dce1d7;--muted:#9ba79d;--acid:#d5ea88;--panel:rgba(13,20,18,.83);--line:rgba(221,233,208,.16);--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--body:'Manrope',sans-serif}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101613;color:var(--ink);font-family:var(--body)}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:#17201d;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 35%,rgba(4,9,8,.35) 78%,rgba(3,6,6,.76) 140%),linear-gradient(180deg,rgba(5,10,9,.56),transparent 25%,transparent 68%,rgba(6,10,9,.52);z-index:1}.screen-edge{position:absolute;inset:0;z-index:7;pointer-events:none;border:1px solid rgba(235,240,217,.07);box-shadow:inset 0 0 42px rgba(0,0,0,.24)}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:78px;padding:17px 4.1%;display:flex;align-items:center;border-bottom:1px solid rgba(230,235,215,.12);background:linear-gradient(180deg,rgba(9,15,14,.68),rgba(9,15,14,.12));gap:22px}.wordmark{display:flex;gap:10px;align-items:center;text-decoration:none;color:#eef0df;font:700 12px/.94 var(--display);letter-spacing:1.55px;min-width:176px}.wordmark b{font-weight:700;color:var(--acid)}.mark{font:700 26px/.9 var(--display);color:var(--acid);border:1px solid rgba(213,234,136,.75);padding:4px 8px 5px 7px;transform:skew(-7deg)}.chapter-label{display:flex;align-items:center;gap:11px;color:#c0c9bd;font:10px var(--mono);letter-spacing:1px}.chapter-label i{width:3px;height:3px;border-radius:50%;background:#738078;margin:0 4px}.live-dot,.objective-dot{width:6px;height:6px;display:inline-block;border-radius:50%;background:var(--acid);box-shadow:0 0 9px rgba(213,234,136,.55)}.topbar .icon-button{margin-left:auto;width:34px;height:34px;border:1px solid var(--line);background:rgba(10,17,15,.55);font:17px var(--mono);color:#c3cdc0;cursor:pointer}.topbar .icon-button+.icon-button{margin-left:-14px}.icon-button:hover{border-color:var(--acid);color:var(--acid)}.game-hud{position:absolute;inset:0;z-index:3;pointer-events:none}.hud-left{position:absolute;top:100px;left:4.1%;width:292px}.survivor-card,.objective-card,.threat-card{background:linear-gradient(135deg,rgba(13,20,18,.91),rgba(13,19,17,.75));border:1px solid var(--line);backdrop-filter:blur(8px)}.survivor-card{padding:13px 13px 12px;display:grid;grid-template-columns:45px 1fr;column-gap:11px;position:relative}.portrait{width:44px;height:50px;position:relative;display:grid;place-items:center;background:linear-gradient(135deg,#455248,#202a26);border:1px solid rgba(225,231,209,.22);color:#dbe4c6;font:700 28px var(--display);clip-path:polygon(0 0,100% 0,100% 84%,82% 100%,0 100%)}.portrait small{position:absolute;right:3px;bottom:2px;font:7px var(--mono);color:#c6d3bc}.eyebrow{display:flex;align-items:center;gap:7px;font:9px var(--mono);letter-spacing:1.2px;color:#9da99c}.survivor-info{display:flex;flex-direction:column;justify-content:center;gap:3px}.survivor-info strong{font:600 16px var(--display);letter-spacing:.7px;color:#e5e9da}.dayline{font:8px var(--mono);letter-spacing:.4px;color:#89968a}.dayline i{color:var(--acid);font-style:normal}.status-bars{grid-column:1/3;display:flex;flex-direction:column;gap:7px;margin-top:12px;padding-top:10px;border-top:1px solid rgba(225,231,209,.1)}.bar-row{display:grid;grid-template-columns:49px 1fr 22px;gap:7px;align-items:center;color:#8f9b8e;font:8px var(--mono);letter-spacing:.6px}.bar-row b{font:8px var(--mono);color:#b4c0af;text-align:right}.bar{height:3px;background:#37423a}.bar i{display:block;height:100%;transition:width .3s}.health-fill{background:#bd775e;width:82%}.stamina-fill{background:#c9dc82;width:100%}.inventory-strip{margin-top:9px;padding:10px 12px 11px;background:rgba(13,20,18,.77);border:1px solid var(--line);backdrop-filter:blur(8px)}.inventory-label{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:1.1px;color:#9da99c}.inventory-label span{color:#718074}.item-slots{display:flex;gap:6px;margin-top:8px}.item-slot{position:relative;width:42px;height:35px;display:grid;place-items:center;background:rgba(187,203,177,.055);border:1px solid rgba(222,232,210,.13);color:#b5c3b0}.item-slot.active{border-color:rgba(213,234,136,.65);color:var(--acid);background:rgba(213,234,136,.08)}.item-slot span{font-size:17px}.item-slot small{position:absolute;right:4px;bottom:2px;color:#9da99c;font:8px var(--mono)}.hud-right{position:absolute;top:100px;right:4.1%;width:268px}.objective-card{padding:13px 14px 12px}.objective-top{display:flex;align-items:center;justify-content:space-between}.objective-top .eyebrow{font-size:8px}.distance{color:var(--acid);font:9px var(--mono)}.objective-card>strong{display:block;margin-top:11px;font:600 21px/.95 var(--display);letter-spacing:.2px;color:#ebeddf}.objective-card p{margin:7px 0 11px;color:#a8b1a5;font-size:10px;line-height:1.5}.objective-progress{height:2px;background:#344037}.objective-progress i{height:100%;width:7%;display:block;background:var(--acid);transition:width .4s}.threat-card{margin-top:8px;padding:9px 11px;display:flex;align-items:center;gap:9px}.threat-icon{font-size:18px;color:#a4b686}.threat-card .eyebrow{font-size:7px}.threat-card strong{display:block;margin-top:3px;font:500 10px var(--mono);letter-spacing:.4px;color:#d0d6c6}.threat-pips{margin-left:auto;display:flex;gap:3px}.threat-pips i{width:9px;height:3px;background:#49544a}.threat-pips i:first-child{background:#c7d988}.location-tag{position:absolute;left:4.1%;bottom:40px;display:flex;align-items:center;gap:12px;padding:9px 12px;background:rgba(11,17,15,.74);border:1px solid rgba(221,233,208,.15);backdrop-filter:blur(7px)}.location-cross{font-size:22px;color:var(--acid);font-weight:300}.location-tag .eyebrow{font-size:7px}.location-tag strong{display:block;margin-top:3px;font:500 13px var(--display);letter-spacing:.9px}.location-sep{height:22px;width:1px;background:var(--line);margin:0 3px}.location-tag #weather-label{font:8px var(--mono);letter-spacing:.4px;color:#a3afa1}.interaction-prompt{position:absolute;left:50%;bottom:98px;transform:translateX(-50%);align-items:center;gap:10px;padding:8px 12px;background:rgba(12,18,16,.82);border:1px solid rgba(221,233,208,.22);color:#d2dacb;font:9px var(--mono);letter-spacing:1px;opacity:0;transition:opacity .2s;white-space:nowrap}.interaction-prompt.visible{display:flex;opacity:1}.keycap{display:grid;place-items:center;width:22px;height:22px;border:1px solid rgba(213,234,136,.6);color:var(--acid);font:11px var(--mono)}.crosshair{position:absolute;left:50%;top:50%;width:12px;height:12px;z-index:2;opacity:.72;pointer-events:none}.crosshair:before,.crosshair:after,.crosshair span:before,.crosshair span:after{content:'';position:absolute;background:rgba(224,233,209,.7)}.crosshair:before{width:1px;height:4px;top:0;left:5px}.crosshair:after{width:1px;height:4px;bottom:0;left:5px}.crosshair span:before{height:1px;width:4px;left:0;top:5px}.crosshair span:after{height:1px;width:4px;right:0;top:5px}.toast{position:absolute;top:79px;left:50%;transform:translateX(-50%) translateY(-10px);padding:9px 14px;background:rgba(12,18,16,.92);border:1px solid rgba(213,234,136,.35);font:9px var(--mono);letter-spacing:.7px;color:var(--acid);opacity:0;transition:.25s}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}.start-screen{position:absolute;inset:0;z-index:6;display:flex;align-items:center;background:linear-gradient(90deg,rgba(7,12,11,.9) 0%,rgba(8,13,12,.76) 29%,rgba(7,12,10,.18) 68%,rgba(7,12,10,.08));transition:opacity .7s,visibility .7s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-grain{position:absolute;inset:0;opacity:.12;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.start-copy{position:relative;margin-left:12.4%;margin-top:14px;width:420px}.start-copy>.eyebrow{font-size:9px;letter-spacing:1.6px}.start-copy h1{font:700 clamp(76px,10.5vw,142px)/.72 var(--display);letter-spacing:-3px;margin:25px 0 26px;color:#eff0df;text-shadow:3px 4px 0 rgba(7,11,10,.8);transform:scaleX(.88);transform-origin:left center}.start-copy h1 em{font-style:normal;color:var(--acid);font-weight:500;letter-spacing:1px}.start-deck{margin:0;color:#c3cabe;font-size:13px;line-height:1.85;letter-spacing:.15px}.start-meta{display:flex;justify-content:space-between;margin-top:28px;padding-top:10px;border-top:1px solid rgba(225,231,210,.22);width:280px;color:#929e91;font:8px var(--mono);letter-spacing:1px}.start-meta span:last-child{color:#c5cdbb}.start-meta i{font-style:normal;color:var(--acid)}.primary-button{position:relative;margin-top:16px;display:flex;align-items:center;justify-content:space-between;width:280px;height:47px;padding:0 16px;background:var(--acid);border:0;color:#172019;font:700 11px var(--mono);letter-spacing:1.15px;cursor:pointer;clip-path:polygon(0 0,100% 0,100% 70%,94% 100%,0 100%);transition:background .2s,transform .2s}.primary-button:hover{background:#e2f59b;transform:translateY(-2px)}.primary-button b{font:18px var(--body)}.start-controls{margin-top:19px;color:#b5c0b3;font:8px var(--mono);letter-spacing:.6px}.start-controls i{font-style:normal;color:#829083;margin:0 4px}.start-controls span{color:#637064;margin:0 3px}.start-footer{position:absolute;left:4.1%;right:4.1%;bottom:24px;display:flex;justify-content:space-between;color:#869186;font:8px var(--mono);letter-spacing:1px}.dialogue-overlay,.pause-overlay{position:absolute;inset:0;z-index:8;display:flex;align-items:flex-end;justify-content:center;padding:35px 20px 8%;background:linear-gradient(0deg,rgba(5,10,9,.94),rgba(5,10,9,.55) 54%,rgba(5,10,9,.25));backdrop-filter:blur(2px)}.dialogue-overlay.hidden,.pause-overlay.hidden{display:none}.dialogue-card{width:min(650px,90vw);border-top:1px solid rgba(213,234,136,.54);padding:19px 22px 15px;background:linear-gradient(120deg,rgba(13,19,17,.94),rgba(13,18,17,.79))}.dialogue-kicker{display:flex;align-items:center;gap:9px;font:9px var(--mono);letter-spacing:1px;color:var(--acid)}.dialogue-time{margin-left:auto;color:#718074}.dialogue-card h2{margin:13px 0 7px;font:600 27px var(--display);letter-spacing:.3px;color:#edf0e3}.dialogue-card>p{max-width:560px;margin:0;color:#b4beb1;font-size:12px;line-height:1.8}.choice-list{display:flex;flex-direction:column;margin-top:17px;border-top:1px solid var(--line)}.choice{display:flex;align-items:center;gap:12px;padding:12px 4px;border:0;border-bottom:1px solid rgba(221,233,208,.1);background:transparent;text-align:left;color:#d1d9cb;font-size:11px;cursor:pointer;transition:color .15s,padding .15s}.choice:hover{color:var(--acid);padding-left:9px}.choice span{font:10px var(--mono);color:var(--acid)}.dialogue-note{display:flex;justify-content:space-between;margin-top:13px;color:#778477;font:8px var(--mono);letter-spacing:.9px}.dialogue-note span{color:var(--acid)}.pause-overlay{align-items:center;background:rgba(7,12,11,.79);backdrop-filter:blur(8px)}.pause-card{width:min(380px,90vw);padding:28px;border:1px solid var(--line);background:rgba(15,22,19,.93)}.pause-card h2{font:700 43px/.9 var(--display);margin:22px 0 10px;color:#e8eddd}.pause-card p{color:#aab5a8;font-size:12px}.pause-card .primary-button{width:100%;margin-top:24px}.quiet-button{width:100%;border:0;background:transparent;padding:14px;color:#a2ada0;font:9px var(--mono);letter-spacing:1px;cursor:pointer}.quiet-button:hover{color:var(--acid)}.pause-controls{border-top:1px solid var(--line);padding-top:14px;margin-top:8px;color:#d4dec8;font:9px/2 var(--mono)}.pause-controls span{color:#849184;margin-left:10px}.mobile-controls{display:none}.screen-shake{animation:shake .2s linear}.hit-flash{animation:flash .2s}@keyframes shake{25%{transform:translate(3px,-2px)}50%{transform:translate(-3px,1px)}75%{transform:translate(2px,2px)}}@keyframes flash{50%{filter:brightness(1.7) sepia(.5)}}
@media(max-width:700px){.topbar{height:60px;padding:11px 15px;gap:10px}.wordmark{min-width:auto;font-size:10px;gap:7px}.mark{font-size:21px;padding:3px 6px}.chapter-label{font-size:8px;gap:6px;margin-left:auto}.chapter-label i,.chapter-label #zone-name{display:none}.topbar .icon-button{width:29px;height:29px;font-size:14px}.topbar .icon-button+.icon-button{margin-left:-5px}.hud-left{left:13px;top:72px;width:208px}.survivor-card{padding:8px;grid-template-columns:35px 1fr;column-gap:8px}.portrait{width:35px;height:40px;font-size:23px}.survivor-info strong{font-size:13px}.eyebrow{font-size:7px}.dayline{font-size:7px}.status-bars{margin-top:8px;padding-top:7px;gap:5px}.inventory-strip{padding:7px;margin-top:6px}.item-slot{width:33px;height:29px}.item-slots{margin-top:6px}.hud-right{right:13px;top:72px;width:min(190px,45vw)}.objective-card{padding:9px}.objective-card>strong{font-size:17px;margin-top:8px}.objective-card p{font-size:9px;margin:5px 0 8px}.objective-top .eyebrow{font-size:6px}.threat-card{padding:7px;gap:6px}.threat-card strong{font-size:8px}.threat-pips i{width:6px}.location-tag{left:12px;bottom:84px;gap:8px;padding:7px 9px}.location-tag strong{font-size:11px}.location-tag #weather-label{font-size:7px}.location-sep{height:18px}.location-cross{font-size:18px}.interaction-prompt{bottom:145px;font-size:8px}.start-copy{margin-left:8%;width:85%;margin-top:0}.start-copy h1{font-size:clamp(74px,18vw,112px);margin:23px 0}.start-deck{font-size:12px}.start-meta{margin-top:23px}.start-footer{left:15px;right:15px;bottom:15px;font-size:7px}.start-controls{font-size:7px}.mobile-controls{position:absolute;display:flex;z-index:4;bottom:12px;left:12px;right:12px;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;background:rgba(15,23,20,.75);border:1px solid rgba(220,232,210,.26);color:#d4dfca;touch-action:none}.dpad{display:flex;flex-direction:column;align-items:center;gap:3px}.dpad>button,.dpad div button{width:37px;height:34px;font-size:13px}.dpad div{display:flex;gap:3px}.mobile-actions{display:flex;align-items:flex-end;gap:8px}.mobile-actions button{height:38px;min-width:58px;font:8px var(--mono);letter-spacing:.6px}.mobile-actions .action-main{width:52px;height:52px;border-radius:50%;border-color:rgba(213,234,136,.65);color:var(--acid)}.dialogue-overlay{padding:20px 10px 9%}.dialogue-card{width:100%;padding:15px}.dialogue-card h2{font-size:24px}.dialogue-card>p{font-size:11px}.choice{font-size:10px;padding:11px 3px}.pause-card{padding:23px}.start-screen{background:linear-gradient(90deg,rgba(7,12,11,.87),rgba(8,13,12,.52) 70%,rgba(7,12,10,.26))}}
