(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { start: $('start-screen'), startButton: $('start-button'), dialogue: $('dialogue-overlay'), pause: $('pause-overlay'), prompt: $('interaction-prompt'), promptCopy: $('prompt-copy'), objective: $('objective-title'), objectiveCopy: $('objective-copy'), distance: $('distance'), progress: $('objective-progress'), health: $('health-fill'), healthValue: $('health-value'), stamina: $('stamina-fill'), staminaValue: $('stamina-value'), threat: $('threat-label'), toast: $('toast'), zone: $('zone-name'), chapter: $('chapter-name'), location: $('location-label'), weather: $('weather-label'), sound: $('sound-toggle') };
  let W = 0, H = 0, dpr = 1, last = 0, started = false, paused = false, dialogueOpen = false, soundOn = false;
  const player = { x: 0, y: 120, health: 82, stamina: 100, sneaking: false, facing: 1, moving: false, step: 0, invuln: 0 };
  const state = { objective: 0, searched: false, signalFound: false, trust: 0, infectedCleared: false, bandages: 1, food: 1, scrap: 0, day: 1, kills: 0 };
  const keys = new Set(), rain = [], debris = [], buildings = [], props = [], infected = [];
  let audioCtx = null, toastTimer = 0;
  const rnd = (n) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
  function resize(){ dpr=Math.min(devicePixelRatio||1,2); W=innerWidth; H=innerHeight; canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0); }
  function initWorld(){
    // Long, discoverable corridor through a drowned city, with distinct landmarks and scavenging stops.
    const sides=[-1,1];
    for(let i=0;i<32;i++){
      const y=-1400+i*125;
      for(const side of sides){
        let x=side*(390+rnd(i*9+side+3)*330);
        buildings.push({x,y:y+rnd(i*4+side+15)*65,w:190+rnd(i*7+side+4)*200,d:145+rnd(i*5+side+21)*95,h:190+rnd(i*11+side+2)*360,side,kind:rnd(i*12+side+1)});
      }
    }
    for(let i=0;i<190;i++){ const y=-1500+i*18; const side=rnd(i+5)>.5?1:-1; props.push({x:side*(210+rnd(i*2+8)*225),y:y+rnd(i+2)*16,type:rnd(i+15)}); }
    for(let i=0;i<170;i++){debris.push({x:(rnd(i*3+9)-.5)*380,y:-1650+rnd(i*6+2)*3600,r:2+rnd(i+1)*9,type:rnd(i+33)});}
    for(let i=0;i<55;i++){rain.push({x:Math.random()*W,y:Math.random()*H,len:5+Math.random()*12,speed:360+Math.random()*400,alpha:.09+Math.random()*.22});}
    // Hand-placed interactive set pieces.
    props.push({x:75,y:-180,type:.91,kind:'crate',name:'Supply crate',searched:false});
    props.push({x:-130,y:-430,type:.91,kind:'radio',name:'Emergency radio',searched:false});
    props.push({x:30,y:-710,type:.91,kind:'med',name:'Field dressing',searched:false});
    props.push({x:-60,y:-1010,type:.91,kind:'note',name:'Waterproof notebook',searched:false});
    infected.push({x:-90,y:-555,alive:true,alert:0,walk:0});
    infected.push({x:120,y:-660,alive:true,alert:0,walk:0});
  }
  function project(x,y){const depth=y-player.y;const s=Math.max(.43,Math.min(1.15,.88+depth*.00035));return{x:W*.5+(x-player.x)*s,y:H*.64+depth*s,s};}
  function poly(points,fill,stroke=null,width=1){ctx.beginPath();points.forEach((p,i)=>{const q=project(p[0],p[1]);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
  function drawBackground(t){
    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1b2926');sky.addColorStop(.38,'#35443c');sky.addColorStop(.72,'#536052');sky.addColorStop(1,'#222c25');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // smoky dawn aperture
    const glow=ctx.createRadialGradient(W*.52,H*.34,5,W*.52,H*.34,H*.65);glow.addColorStop(0,'rgba(200,190,145,.24)');glow.addColorStop(.4,'rgba(110,133,109,.09)');glow.addColorStop(1,'rgba(5,10,9,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
    const horizon=H*.37;
    for(let i=0;i<13;i++){
      const off=(i-6)*W*.12;const bh=90+rnd(i+45)*210;const bw=38+rnd(i+27)*52;const bx=W*.5+off;
      ctx.fillStyle=i%3?'#293831':'#35443a';ctx.fillRect(bx-bw/2,horizon-bh,bw,bh);
      ctx.fillStyle='rgba(8,15,13,.4)';for(let j=0;j<4;j++)ctx.fillRect(bx-bw*.4+j*bw*.22,horizon-bh+20,bw*.1,bh*.76);
      ctx.beginPath();ctx.moveTo(bx-bw/2,horizon-bh);ctx.lineTo(bx-bw*.28,horizon-bh-18-rnd(i)*24);ctx.lineTo(bx-bw*.05,horizon-bh+4);ctx.lineTo(bx+bw*.26,horizon-bh-26);ctx.lineTo(bx+bw/2,horizon-bh-6);ctx.lineTo(bx+bw/2,horizon);ctx.lineTo(bx-bw/2,horizon);ctx.fillStyle='#25332d';ctx.fill();
    }
    ctx.fillStyle='rgba(179,189,159,.09)';ctx.fillRect(0,horizon-12,W,22);
    // buildings and facades, sorted back to front
    const visible=buildings.filter(b=>b.y>player.y-1500&&b.y<player.y+600).sort((a,b)=>a.y-b.y);
    visible.forEach(b=>drawBuilding(b));
    // Road, sidewalks, curb and painted broken center lines
    poly([[-210,player.y-1900],[210,player.y-1900],[355,player.y+1000],[-355,player.y+1000]],'#414640');
    poly([[-244,player.y-1900],[-210,player.y-1900],[-355,player.y+1000],[-405,player.y+1000]],'#55564b');
